711			node := p.parseExpression(0)
712			nodes = append(nodes, node)
713		}
714	end:
715		p.expect(Bracket, "]")
716	
717		node := p.createNode(&ArrayNode{Nodes: nodes}, token.Location)
718		if node == nil {
719			return nil
720		}
721		return node
722	}
723	
724	func (p *Parser) parseMapExpression(token Token) Node {
725		p.expect(Bracket, "{")
726	
727		nodes := make([]Node, 0)
728		for !p.current.Is(Bracket, "}") && p.err == nil {
729			if len(nodes) > 0 {
730				p.expect(Operator, ",")
731				if p.current.Is(Bracket, "}") {
732					goto end
733				}
734				if p.current.Is(Operator, ",") {
735					p.error("unexpected token %v", p.current)
736				}
737			}
738	
739			var key Node
740			// Map key can be one of:
741			//  * number
742			//  * string
743			//  * identifier, which is equivalent to a string
744			//  * expression, which must be enclosed in parentheses -- (1 + 2)
745			if p.current.Is(Number) || p.current.Is(String) || p.current.Is(Identifier) {
746				key = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
747				if key == nil {
748					return nil
749				}
750				p.next()
751			} else if p.current.Is(Bracket, "(") {
752				key = p.parseExpression(0)
753			} else {
754				p.error("a map key must be a quoted string, a number, a identifier, or an expression enclosed in parentheses (unexpected token %v)", p.current)
755			}
756	
757			p.expect(Operator, ":")
758	
759			node := p.parseExpression(0)
760			pair := p.createNode(&PairNode{Key: key, Value: node}, token.Location)

760			pair := p.createNode(&PairNode{Key: key, Value: node}, token.Location)
761			if pair == nil {
762				return nil
763			}
764			nodes = append(nodes, pair)
765		}
766	
767	end:
768		p.expect(Bracket, "}")
769	
770		node := p.createNode(&MapNode{Pairs: nodes}, token.Location)
771		if node == nil {
772			return nil
773		}
774		return node
775	}
776	
777	func (p *Parser) parsePostfixExpression(node Node) Node {
778		postfixToken := p.current
779		for (postfixToken.Is(Operator) || postfixToken.Is(Bracket)) && p.err == nil {
780			optional := postfixToken.Value == "?."
781		parseToken:
782			if postfixToken.Value == "." || postfixToken.Value == "?." {
783				p.next()
784	
785				propertyToken := p.current
786				if optional && propertyToken.Is(Bracket, "[") {
787					postfixToken = propertyToken
788					goto parseToken
789				}
790				p.next()
791	
792				if propertyToken.Kind != Identifier &&
793					// Operators like "not" and "matches" are valid methods or property names.
794					(propertyToken.Kind != Operator || !utils.IsValidIdentifier(propertyToken.Value)) {
795					p.error("expected name")
796				}
797	
798				property := p.createNode(&StringNode{Value: propertyToken.Value}, propertyToken.Location)
799				if property == nil {
800					return nil
801				}
802	
803				chainNode, isChain := node.(*ChainNode)
804				optional := postfixToken.Value == "?."
805	
806				if isChain {
807					node = chainNode.Node
808				}
809	
810				memberNode := p.createMemberNode(&MemberNode{
811					Node:     node,
812					Property: property,
813					Optional: optional,
814				}, propertyToken.Location)
815				if memberNode == nil {
816					return nil
817				}
818	
819				if p.current.Is(Bracket, "(") {
820					memberNode.Method = true
821					node = p.createNode(&CallNode{
822						Callee:    memberNode,
823						Arguments: p.parseArguments([]Node{}),
824					}, propertyToken.Location)
825					if node == nil {
826						return nil
827					}
828				} else {
829					node = memberNode
830				}
831	
832				if isChain || optional {
833					node = p.createNode(&ChainNode{Node: node}, propertyToken.Location)
834					if node == nil {
835						return nil
836					}
837				}
838	
839			} else if postfixToken.Value == "[" {
840				p.next()
841				var from, to Node
842	
843				if p.current.Is(Operator, ":") { // slice without from [:1]
844					p.next()
845	
846					if !p.current.Is(Bracket, "]") { // slice without from and to [:]
847						to = p.parseExpression(0)
848					}
849	
850					node = p.createNode(&SliceNode{
851						Node: node,
852						To:   to,
853					}, postfixToken.Location)
854					if node == nil {
855						return nil
856					}
857					p.expect(Bracket, "]")
858	
859				} else {
860	
861					from = p.parseExpression(0)
862	
863					if p.current.Is(Operator, ":") {
864						p.next()
865	
866						if !p.current.Is(Bracket, "]") { // slice without to [1:]
867							to = p.parseExpression(0)
868						}
869	
870						node = p.createNode(&SliceNode{
871							Node: node,
872							From: from,
873							To:   to,
874						}, postfixToken.Location)
875						if node == nil {
876							return nil
877						}
878						p.expect(Bracket, "]")
879	
880					} else {
881						// Slice operator [:] was not found,
882						// it should be just an index node.
883						node = p.createNode(&MemberNode{
884							Node:     node,
885							Property: from,
886							Optional: optional,
887						}, postfixToken.Location)
888						if node == nil {
889							return nil
890						}
891						if optional {
892							node = p.createNode(&ChainNode{Node: node}, postfixToken.Location)
893							if node == nil {
894								return nil
895							}
896						}
897						p.expect(Bracket, "]")
898					}
899				}
900			} else {
901				break
902			}
903			postfixToken = p.current
904		}
905		return node
906	}
907	func (p *Parser) parseComparison(left Node, token Token, precedence int) Node {
908		var rootNode Node
909		for {
910			comparator := p.parseExpression(precedence + 1)
911			cmpNode := p.createNode(&BinaryNode{
912				Operator: token.Value,
913				Left:     left,
914				Right:    comparator,
915			}, token.Location)
916			if cmpNode == nil {
917				return nil
918			}
919			if rootNode == nil {
920				rootNode = cmpNode
921			} else {
922				rootNode = p.createNode(&BinaryNode{
923					Operator: "&&",
924					Left:     rootNode,
925					Right:    cmpNode,
926				}, token.Location)
927				if rootNode == nil {
928					return nil
929				}
930			}
931	
932			left = comparator
933			token = p.current
934			if !(token.Is(Operator) && operator.IsComparison(token.Value) && p.err == nil) {
935				break
936			}
937			p.next()
938		}
939		return rootNode
940	}

package ast

import (
	"reflect"

	"github.com/expr-lang/expr/checker/nature"
	"github.com/expr-lang/expr/file"
)

var (
	anyType = reflect.TypeOf(new(any)).Elem()
)

// Node represents items of abstract syntax tree.
type Node interface {
	Location() file.Location
	SetLocation(file.Location)
	Nature() *nature.Nature
	SetNature(nature.Nature)
	Type() reflect.Type
	SetType(reflect.Type)
	String() string
}

// Patch replaces the node with a new one.
// Location information is preserved.
// Type information is lost.
func Patch(node *Node, newNode Node) {
	newNode.SetLocation((*node).Location())
	*node = newNode
}

// base is a base struct for all nodes.
type base struct {
	loc    file.Location
	nature nature.Nature
}

// Location returns the location of the node in the source code.
func (n *base) Location() file.Location {
	return n.loc
}

// SetLocation sets the location of the node in the source code.
func (n *base) SetLocation(loc file.Location) {
	n.loc = loc
}

// Nature returns the nature of the node.
func (n *base) Nature() *nature.Nature {
	return &n.nature
}

// SetNature sets the nature of the node.
func (n *base) SetNature(nature nature.Nature) {
	n.nature = nature
}

// Type returns the type of the node.
func (n *base) Type() reflect.Type {
	if n.nature.Type == nil {
		return anyType
	}
	return n.nature.Type
}

// SetType sets the type of the node.
func (n *base) SetType(t reflect.Type) {
	n.nature = nature.FromType(t)
}

// NilNode represents nil.
type NilNode struct {
	base
}

// IdentifierNode represents an identifier.
type IdentifierNode struct {
	base
	Value string // Name of the identifier. Like "foo" in "foo.bar".
}

// IntegerNode represents an integer.
type IntegerNode struct {
	base
	Value int // Value of the integer.
}

// FloatNode represents a float.
type FloatNode struct {
	base
	Value float64 // Value of the float.
}

// BoolNode represents a boolean.
type BoolNode struct {
	base
	Value bool // Value of the boolean.
}

// StringNode represents a string.
type StringNode struct {
	base
	Value string // Value of the string.
}

// BytesNode represents a byte slice.
type BytesNode struct {
	base
	Value []byte // Value of the byte slice.
}

// ConstantNode represents a constant.
// Constants are predefined values like nil, true, false, array, map, etc.
// The parser.Parse will never generate ConstantNode, it is only generated
// by the optimizer.
type ConstantNode struct {
	base
	Value any // Value of the constant.
}

// UnaryNode represents a unary operator.
type UnaryNode struct {
	base
	Operator string // Operator of the unary operator. Like "!" in "!foo" or "not" in "not foo".
	Node     Node   // Node of the unary operator. Like "foo" in "!foo".
}

// BinaryNode represents a binary operator.
type BinaryNode struct {
	base
	Operator string // Operator of the binary operator. Like "+" in "foo + bar" or "matches" in "foo matches bar".
	Left     Node   // Left node of the binary operator.
	Right    Node   // Right node of the binary operator.
}

// ChainNode represents an optional chaining group.
// A few MemberNode nodes can be chained together,
// and will be wrapped in a ChainNode. Example:
//
//	foo.bar?.baz?.qux
//
// The whole chain will be wrapped in a ChainNode.
type ChainNode struct {
	base
	Node Node // Node of the chain.
}

// MemberNode represents a member access.
// It can be a field access, a method call,
// or an array element access.
// Example:
//
//	foo.bar or foo["bar"]
//	foo.bar()
//	array[0]
type MemberNode struct {
	base
	Node     Node // Node of the member access. Like "foo" in "foo.bar".
	Property Node // Property of the member access. For property access it is a StringNode.
	Optional bool // If true then the member access is optional. Like "foo?.bar".
	Method   bool
}

// SliceNode represents access to a slice of an array.
// Example:
//
//	array[1:4]
type SliceNode struct {
	base
	Node Node // Node of the slice. Like "array" in "array[1:4]".
	From Node // From an index of the array. Like "1" in "array[1:4]".
	To   Node // To an index of the array. Like "4" in "array[1:4]".
}

// CallNode represents a function or a method call.
type CallNode struct {
	base
	Callee    Node   // Node of the call. Like "foo" in "foo()".
	Arguments []Node // Arguments of the call.
}

// BuiltinNode represents a builtin function call.
type BuiltinNode struct {
	base
	Name      string // Name of the builtin function. Like "len" in "len(foo)".
	Arguments []Node // Arguments of the builtin function.
	Throws    bool   // If true then accessing a field or array index can throw an error. Used by optimizer.
	Map       Node   // Used by optimizer to fold filter() and map() builtins.
	Threshold *int   // Used by optimizer for count() early termination.
}

// PredicateNode represents a predicate.
// Example:
//
//	filter(foo, .bar == 1)
//
// The predicate is ".bar == 1".
type PredicateNode struct {
	base
	Node Node // Node of the predicate body.
}

// PointerNode represents a pointer to a current value in predicate.
type PointerNode struct {
	base
	Name string // Name of the pointer. Like "index" in "#index".
}

// ConditionalNode represents a ternary operator or if/else operator.
type ConditionalNode struct {
	base
	Ternary bool // Is it ternary or if/else operator?
	Cond    Node // Condition
	Exp1    Node // Expression 1
	Exp2    Node // Expression 2
}

// VariableDeclaratorNode represents a variable declaration.
type VariableDeclaratorNode struct {
	base
	Name  string // Name of the variable. Like "foo" in "let foo = 1; foo + 1".
	Value Node   // Value of the variable. Like "1" in "let foo = 1; foo + 1".
	Expr  Node   // Expression of the variable. Like "foo + 1" in "let foo = 1; foo + 1".
}

// SequenceNode represents a sequence of nodes separated by semicolons.
// All nodes are executed, only the last node will be returned.
type SequenceNode struct {
	base
	Nodes []Node
}

// ArrayNode represents an array.
type ArrayNode struct {
	base
	Nodes []Node // Nodes of the array.
}

// MapNode represents a map.
type MapNode struct {
	base
	Pairs []Node // PairNode nodes.
}

// PairNode represents a key-value pair of a map.
type PairNode struct {
	base
	Key   Node // Key of the pair.
	Value Node // Value of the pair.
}

package ast

import "fmt"

type Visitor interface {
	Visit(node *Node)
}

func Walk(node *Node, v Visitor) {
	if *node == nil {
		return
	}
	switch n := (*node).(type) {
	case *NilNode:
	case *IdentifierNode:
	case *IntegerNode:
	case *FloatNode:
	case *BoolNode:
	case *StringNode:
	case *BytesNode:
	case *ConstantNode:
	case *UnaryNode:
		Walk(&n.Node, v)
	case *BinaryNode:
		Walk(&n.Left, v)
		Walk(&n.Right, v)
	case *ChainNode:
		Walk(&n.Node, v)
	case *MemberNode:
		Walk(&n.Node, v)
		Walk(&n.Property, v)
	case *SliceNode:
		Walk(&n.Node, v)
		if n.From != nil {
			Walk(&n.From, v)
		}
		if n.To != nil {
			Walk(&n.To, v)
		}
	case *CallNode:
		Walk(&n.Callee, v)
		for i := range n.Arguments {
			Walk(&n.Arguments[i], v)
		}
	case *BuiltinNode:
		for i := range n.Arguments {
			Walk(&n.Arguments[i], v)
		}
	case *PredicateNode:
		Walk(&n.Node, v)
	case *PointerNode:
	case *VariableDeclaratorNode:
		Walk(&n.Value, v)
		Walk(&n.Expr, v)
	case *SequenceNode:
		for i := range n.Nodes {
			Walk(&n.Nodes[i], v)
		}
	case *ConditionalNode:
		Walk(&n.Cond, v)
		Walk(&n.Exp1, v)
		Walk(&n.Exp2, v)
	case *ArrayNode:
		for i := range n.Nodes {
			Walk(&n.Nodes[i], v)
		}
	case *MapNode:
		for i := range n.Pairs {
			Walk(&n.Pairs[i], v)
		}
	case *PairNode:
		Walk(&n.Key, v)
		Walk(&n.Value, v)
	default:
		panic(fmt.Sprintf("undefined node type (%T)", node))
	}

	v.Visit(node)
}
=====FIND=====
package ast

func Find(node Node, fn func(node Node) bool) Node {
	v := &finder{fn: fn}
	Walk(&node, v)
	return v.node
}

type finder struct {
	node Node
	fn   func(node Node) bool
}

func (f *finder) Visit(node *Node) {
	if f.fn(*node) {
		f.node = *node
	}
}
